  def self.svg(name, size: 20, css_class: nil)
    paths = PATHS.fetch(name.to_sym) { PATHS[:info] }
    classes = ['icon', css_class].compact.join(' ')
    %(<svg class="#{classes}" width="#{size}" height="#{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" ) +
      %(stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">#{paths}</svg>)
  end
